-- Recurring Schedule Defaults V1: Product Owner locked contract, 2026-10-04.
-- No backfill. Calendar reads, historical migrations and occurrence plans stay unchanged.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

-- BEGIN GENERATED TIMEZONE CATALOG V1
-- Generated offline from pinned TZif bytes; never hand edit.
-- Generator input only. This SQL is embedded in the self-contained migration.
CREATE FUNCTION system_internal.tzdb_rule_part_valid_v1(r jsonb) RETURNS boolean
 LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $f$
 DECLARE i integer; k text;
 BEGIN
 IF r IS NULL OR jsonb_typeof(r)<>'array' THEN RETURN false; END IF;
 IF jsonb_array_length(r)<>6 THEN RETURN false; END IF;
 k:=r->>0;
 FOR i IN 1..5 LOOP
  IF jsonb_typeof(r->i)<>'number' OR (r->>i)!~ '^-?[0-9]+$' OR (r->>i)::numeric NOT BETWEEN -604799 AND 604799 THEN RETURN false; END IF;
 END LOOP;
 RETURN coalesce(CASE k
  WHEN 'M' THEN (r->>1)::integer BETWEEN 1 AND 12 AND (r->>2)::integer BETWEEN 1 AND 5 AND (r->>3)::integer BETWEEN 0 AND 6 AND r->>4='0'
  WHEN 'J' THEN r->>1='0' AND r->>2='0' AND r->>3='0' AND (r->>4)::integer BETWEEN 1 AND 365
  WHEN 'D' THEN r->>1='0' AND r->>2='0' AND r->>3='0' AND (r->>4)::integer BETWEEN 0 AND 365
  ELSE false END,false);
 END $f$;
CREATE FUNCTION system_internal.tzdb_rule_valid_v1(r jsonb) RETURNS boolean
 LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $f$
 DECLARE i integer;
 BEGIN
 IF r IS NULL OR jsonb_typeof(r)<>'array' THEN RETURN false; END IF;
 IF jsonb_array_length(r)<>7 THEN RETURN false; END IF;
 IF r->>0='none' THEN RETURN r='["none",null,null,null,null,null,null]'::jsonb; END IF;
 IF coalesce(r->>0,'') NOT IN ('fixed','dst') OR jsonb_typeof(r->3)<>'boolean' THEN RETURN false; END IF;
 FOR i IN 1..CASE WHEN r->>0='dst' THEN 2 ELSE 1 END LOOP
  IF jsonb_typeof(r->i)<>'number' OR (r->>i)!~ '^-?[0-9]+$' OR (r->>i)::numeric NOT BETWEEN -89999 AND 93599 THEN RETURN false; END IF;
 END LOOP;
 IF r->>0='fixed' THEN RETURN r->2='null'::jsonb AND r->4='null'::jsonb AND r->5='null'::jsonb AND r->6='null'::jsonb; END IF;
 RETURN jsonb_typeof(r->4)='boolean' AND system_internal.tzdb_rule_part_valid_v1(r->5) AND system_internal.tzdb_rule_part_valid_v1(r->6);
 END $f$;
CREATE TABLE system_internal.tzdb_release_v1 (
 release_id text PRIMARY KEY, identity jsonb NOT NULL CHECK(jsonb_typeof(identity)='array' AND jsonb_array_length(identity)=8),
 tzdb_version text GENERATED ALWAYS AS (identity->>0) STORED,
 source_sha256 text GENERATED ALWAYS AS (identity->>1) STORED,
 generated_dataset_sha256 text GENERATED ALWAYS AS (identity->>2) STORED,
 generator_version text GENERATED ALWAYS AS (identity->>3) STORED,
 resolver_semantics_version text GENERATED ALWAYS AS (identity->>4) STORED,
 sealed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE system_internal.tzdb_active_v1 (
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
 release_id text NOT NULL REFERENCES system_internal.tzdb_release_v1(release_id)
);
CREATE TABLE system_internal.tzdb_zone_v1 (
 release_id text NOT NULL REFERENCES system_internal.tzdb_release_v1(release_id), zone_name text NOT NULL,
 manifest jsonb NOT NULL CHECK(jsonb_typeof(manifest)='array' AND jsonb_array_length(manifest)=9),
 manifest_sha256 text NOT NULL CHECK(manifest_sha256 ~ '^[a-f0-9]{64}$'), PRIMARY KEY(release_id,zone_name)
);
CREATE TABLE system_internal.tzdb_offset_v1 (
 release_id text NOT NULL,zone_name text NOT NULL,offset_seconds integer NOT NULL CHECK(offset_seconds BETWEEN -89999 AND 93599),
 PRIMARY KEY(release_id,zone_name,offset_seconds),
 FOREIGN KEY(release_id,zone_name) REFERENCES system_internal.tzdb_zone_v1(release_id,zone_name)
);
CREATE TABLE system_internal.tzdb_era_v1 (
 release_id text NOT NULL,zone_name text NOT NULL,utc_start timestamptz NOT NULL,utc_end timestamptz NOT NULL,
 offset_seconds integer NOT NULL,specified boolean NOT NULL,
 PRIMARY KEY(release_id,zone_name,utc_start), CHECK(utc_start<utc_end),
 FOREIGN KEY(release_id,zone_name,offset_seconds) REFERENCES system_internal.tzdb_offset_v1(release_id,zone_name,offset_seconds)
);
CREATE TABLE system_internal.tzdb_rule_v1 (
 release_id text NOT NULL,zone_name text NOT NULL,future_start timestamptz NOT NULL,rule jsonb NOT NULL,
 PRIMARY KEY(release_id,zone_name),
 FOREIGN KEY(release_id,zone_name) REFERENCES system_internal.tzdb_zone_v1(release_id,zone_name),
 CHECK(system_internal.tzdb_rule_valid_v1(rule))
);
CREATE TYPE system_internal.tzdb_context_v1 AS (
 release_id text,zone_name text,offsets integer[],future_start timestamptz,rule jsonb
);
CREATE TYPE system_internal.tzdb_state_v1 AS (offset_seconds integer,specified boolean);

CREATE FUNCTION system_internal.tzdb_hash_v1(p_value jsonb) RETURNS text
 LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $f$
 SELECT encode(sha256(convert_to(replace(p_value::text,' ',''),'UTF8')),'hex') $f$;
CREATE FUNCTION system_internal.tzdb_bound_v1(p_value timestamptz) RETURNS text
 LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $f$
 SELECT CASE WHEN isfinite(p_value) THEN extract(epoch FROM p_value)::bigint::text ELSE p_value::text END $f$;
CREATE FUNCTION system_internal.tzdb_days_v1(y integer,m integer,d integer) RETURNS bigint
 LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $f$
 WITH a AS (SELECT (y-CASE WHEN m<=2 THEN 1 ELSE 0 END)::bigint AS yr),
 b AS (SELECT yr,floor(yr::numeric/400)::bigint AS era FROM a),
 c AS (SELECT era,yr-era*400 AS yo FROM b)
 SELECT era*146097+yo*365+yo/4-yo/100+(153*(m+CASE WHEN m>2 THEN -3 ELSE 9 END)+2)/5+d-1-719468 FROM c $f$;
CREATE FUNCTION system_internal.tzdb_rule_seconds_v1(r jsonb,y integer) RETURNS bigint
 LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $f$
 DECLARE k text:=r->>0; m integer:=(r->>1)::integer; w integer:=(r->>2)::integer;
 wd integer:=(r->>3)::integer; n integer:=(r->>4)::integer; sh integer:=(r->>5)::integer;
 base bigint; delta integer; len integer; leap boolean:=(y%4=0 AND y%100<>0) OR y%400=0;
 BEGIN
 IF jsonb_array_length(r)<>6 OR sh NOT BETWEEN -604799 AND 604799 OR k NOT IN ('M','J','D') THEN
  RAISE EXCEPTION 'Malformed timezone rule' USING ERRCODE='PZ002'; END IF;
 IF k='M' THEN
  IF m NOT BETWEEN 1 AND 12 OR w NOT BETWEEN 1 AND 5 OR wd NOT BETWEEN 0 AND 6 THEN RAISE EXCEPTION 'Malformed month rule' USING ERRCODE='PZ002'; END IF;
  base:=system_internal.tzdb_days_v1(y,m,1);
  delta:=mod(mod(wd-mod(base+4,7),7)+7,7)+(w-1)*7;
  len:=CASE WHEN m=2 THEN CASE WHEN leap THEN 29 ELSE 28 END ELSE (ARRAY[31,28,31,30,31,30,31,31,30,31,30,31])[m] END;
  IF delta>=len THEN delta:=delta-7; END IF;
  base:=base+delta;
 ELSIF k='J' THEN
  IF n NOT BETWEEN 1 AND 365 THEN RAISE EXCEPTION 'Malformed Julian rule' USING ERRCODE='PZ002'; END IF;
  base:=system_internal.tzdb_days_v1(y,1,1)+n-1+CASE WHEN leap AND n>=60 THEN 1 ELSE 0 END;
 ELSE
  IF n NOT BETWEEN 0 AND 365 THEN RAISE EXCEPTION 'Malformed ordinal rule' USING ERRCODE='PZ002'; END IF;
  base:=system_internal.tzdb_days_v1(y,1,1)+n;
 END IF;
 RETURN base*86400+sh;
 END $f$;

CREATE FUNCTION system_internal.tzdb_future_v1(r jsonb,u timestamptz) RETURNS system_internal.tzdb_state_v1
 LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $f$
 DECLARE mode text:=r->>0; std integer:=(r->>1)::integer; dst integer:=(r->>2)::integer;
 year integer:=extract(year FROM u AT TIME ZONE INTERVAL '0')::integer; y integer;
 second numeric:=extract(epoch FROM u); a bigint; b bigint; latest bigint:=NULL;
 result system_internal.tzdb_state_v1;
 BEGIN
 IF mode='none' THEN RAISE EXCEPTION 'Future timezone data unavailable' USING ERRCODE='PZ002'; END IF;
 IF mode='fixed' THEN RETURN (std,(r->>3)::boolean)::system_internal.tzdb_state_v1; END IF;
 IF mode<>'dst' OR dst IS NULL THEN RAISE EXCEPTION 'Malformed future rule' USING ERRCODE='PZ002'; END IF;
 IF year<0 THEN year:=year+1; END IF; -- PostgreSQL BC -> astronomical year
 FOR y IN year-2..year+2 LOOP
  a:=system_internal.tzdb_rule_seconds_v1(r->5,y)-std;
  b:=system_internal.tzdb_rule_seconds_v1(r->6,y)-dst;
  IF b<=second AND (latest IS NULL OR b>latest) THEN latest:=b;result:=(std,(r->>3)::boolean); END IF;
  -- Start wins ties, including the POSIX all-year-DST representation.
  IF a<=second AND (latest IS NULL OR a>=latest) THEN latest:=a;result:=(dst,(r->>4)::boolean); END IF;
 END LOOP;
 IF latest IS NULL OR result.offset_seconds IS NULL OR result.specified IS NULL THEN RAISE EXCEPTION 'Incomplete future rule' USING ERRCODE='PZ002'; END IF;
 RETURN result;
 END $f$;

CREATE FUNCTION system_internal.tzdb_check_release_v1(p_release text) RETURNS void
 LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $f$
 DECLARE r system_internal.tzdb_release_v1; n bigint; eras bigint; offsets bigint; root text; src text; malformed boolean;
 BEGIN
 SELECT * INTO r FROM system_internal.tzdb_release_v1 WHERE release_id=p_release;
 IF NOT FOUND OR r.identity->>4 IS DISTINCT FROM 'system-tz-v1' OR r.identity->>3 IS DISTINCT FROM 'system-tz-generator-v1'
  OR r.release_id IS DISTINCT FROM 'system-tz-v1/'||system_internal.tzdb_hash_v1(r.identity) THEN
  RAISE EXCEPTION 'Timezone release identity invalid' USING ERRCODE='PZ002'; END IF;
 SELECT count(*),sum((manifest->>4)::integer),sum((manifest->>5)::integer),
  encode(sha256(convert_to(string_agg(zone_name||':'||manifest_sha256||E'\n','' ORDER BY zone_name COLLATE "C"),'UTF8')),'hex'),
  encode(sha256(convert_to(string_agg(zone_name||':'||(manifest->>1)||E'\n','' ORDER BY zone_name COLLATE "C"),'UTF8')),'hex'),
  bool_or(manifest_sha256 IS DISTINCT FROM system_internal.tzdb_hash_v1(manifest) OR manifest->>0 IS DISTINCT FROM zone_name)
 INTO n,eras,offsets,root,src,malformed FROM system_internal.tzdb_zone_v1 WHERE release_id=p_release;
 IF malformed IS DISTINCT FROM false OR root IS DISTINCT FROM r.identity->>2 OR src IS DISTINCT FROM r.identity->>1
  OR n IS DISTINCT FROM (r.identity->>5)::bigint OR eras IS DISTINCT FROM (r.identity->>6)::bigint OR offsets IS DISTINCT FROM (r.identity->>7)::bigint THEN
  RAISE EXCEPTION 'Timezone release manifest invalid' USING ERRCODE='PZ002'; END IF;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_parameter_value THEN
  RAISE EXCEPTION 'Malformed timezone release' USING ERRCODE='PZ002';
 END $f$;

CREATE FUNCTION system_internal.tzdb_active_release_v1() RETURNS text
 LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $f$
 DECLARE value text; BEGIN
 SELECT a.release_id INTO value FROM system_internal.tzdb_active_v1 a JOIN system_internal.tzdb_release_v1 r USING(release_id) WHERE a.singleton AND r.sealed;
 IF value IS NULL THEN RAISE EXCEPTION 'Active timezone release unavailable' USING ERRCODE='PZ002'; END IF;
 PERFORM system_internal.tzdb_check_release_v1(value); RETURN value;
 END $f$;

-- Full per-zone integrity once per materialization batch, not once per endpoint.
CREATE FUNCTION system_internal.tzdb_context_v1(p_release text,p_zone text) RETURNS system_internal.tzdb_context_v1
 LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $f$
 DECLARE z system_internal.tzdb_zone_v1; r system_internal.tzdb_rule_v1; result system_internal.tzdb_context_v1;
 n bigint; h text; invalid boolean; first_at timestamptz; last_at timestamptz; last_explicit timestamptz;
 state system_internal.tzdb_state_v1; e system_internal.tzdb_era_v1;
 BEGIN
 IF p_zone IS NULL THEN RAISE EXCEPTION 'Profile timezone is required' USING ERRCODE='PZ001'; END IF;
 -- A release reference that does not exist is dataset corruption, never an
 -- unsupported Profile zone. Without this the two conditions are indistinguishable
 -- and a corrupt registry is misreported to the caller as PZ003.
 IF NOT EXISTS(SELECT 1 FROM system_internal.tzdb_release_v1 WHERE release_id=p_release) THEN
  RAISE EXCEPTION 'Timezone release unavailable' USING ERRCODE='PZ002'; END IF;
 SELECT * INTO z FROM system_internal.tzdb_zone_v1 WHERE release_id=p_release AND zone_name=p_zone;
 IF NOT FOUND THEN RAISE EXCEPTION 'Profile timezone is unsupported by SYSTEM release' USING ERRCODE='PZ003'; END IF;
 IF z.manifest_sha256 IS DISTINCT FROM system_internal.tzdb_hash_v1(z.manifest) THEN RAISE EXCEPTION 'Timezone manifest corrupt' USING ERRCODE='PZ002'; END IF;
 SELECT array_agg(offset_seconds ORDER BY offset_seconds) INTO result.offsets FROM system_internal.tzdb_offset_v1 WHERE release_id=p_release AND zone_name=p_zone;
 IF cardinality(result.offsets) IS DISTINCT FROM (z.manifest->>5)::integer OR system_internal.tzdb_hash_v1(to_jsonb(result.offsets)) IS DISTINCT FROM z.manifest->>7 THEN
  RAISE EXCEPTION 'Timezone candidates corrupt' USING ERRCODE='PZ002'; END IF;
 SELECT count(*),min(utc_start),max(utc_end),
  encode(sha256(convert_to(string_agg(replace(jsonb_build_array(system_internal.tzdb_bound_v1(utc_start),system_internal.tzdb_bound_v1(utc_end),offset_seconds,specified)::text,' ','')||E'\n','' ORDER BY utc_start),'UTF8')),'hex'),
  bool_or(utc_start>=utc_end OR (previous_end IS NOT NULL AND previous_end<>utc_start))
 INTO n,first_at,last_at,h,invalid FROM (
  SELECT *,lag(utc_end) OVER(ORDER BY utc_start) previous_end FROM system_internal.tzdb_era_v1 WHERE release_id=p_release AND zone_name=p_zone
 ) v;
 IF n IS DISTINCT FROM (z.manifest->>4)::integer OR h IS DISTINCT FROM z.manifest->>6 OR invalid IS DISTINCT FROM false
  OR first_at IS DISTINCT FROM '-infinity'::timestamptz OR last_at IS DISTINCT FROM 'infinity'::timestamptz THEN
  RAISE EXCEPTION 'Timezone eras corrupt' USING ERRCODE='PZ002'; END IF;
 SELECT * INTO r FROM system_internal.tzdb_rule_v1 WHERE release_id=p_release AND zone_name=p_zone;
 IF NOT FOUND OR NOT system_internal.tzdb_rule_valid_v1(r.rule) OR system_internal.tzdb_hash_v1(r.rule) IS DISTINCT FROM z.manifest->>8 OR system_internal.tzdb_bound_v1(r.future_start) IS DISTINCT FROM z.manifest->>3 THEN
  RAISE EXCEPTION 'Timezone future rule corrupt' USING ERRCODE='PZ002'; END IF;
 IF z.manifest->>2 IS NOT NULL THEN last_explicit:=to_timestamp((z.manifest->>2)::bigint); END IF;
 IF (r.rule->>0='none' AND r.future_start<>'infinity') OR
  (r.rule->>0<>'none' AND r.future_start IS DISTINCT FROM coalesce(last_explicit,'-infinity'::timestamptz)) THEN
  RAISE EXCEPTION 'Impossible timezone activation' USING ERRCODE='PZ002'; END IF;
 IF r.rule->>0<>'none' THEN
  state:=system_internal.tzdb_future_v1(r.rule,coalesce(last_explicit,'2000-01-01Z'::timestamptz));
  IF state.offset_seconds<>ALL(result.offsets) THEN RAISE EXCEPTION 'Future offset missing from candidates' USING ERRCODE='PZ002'; END IF;
  IF last_explicit IS NOT NULL THEN
   SELECT * INTO e FROM system_internal.tzdb_era_v1 WHERE release_id=p_release AND zone_name=p_zone AND utc_start<=last_explicit AND utc_end>last_explicit;
   IF NOT FOUND OR (e.offset_seconds,e.specified) IS DISTINCT FROM (state.offset_seconds,state.specified) THEN RAISE EXCEPTION 'Inconsistent footer activation' USING ERRCODE='PZ002'; END IF;
  END IF;
 END IF;
 result.release_id:=p_release; result.zone_name:=p_zone;result.future_start:=r.future_start;result.rule:=r.rule; RETURN result;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_parameter_value THEN
  RAISE EXCEPTION 'Malformed timezone dataset' USING ERRCODE='PZ002';
 END $f$;

CREATE FUNCTION system_internal.tzdb_offset_at_v1(c system_internal.tzdb_context_v1,u timestamptz) RETURNS system_internal.tzdb_state_v1
 LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $f$
 DECLARE result system_internal.tzdb_state_v1;
 BEGIN
 IF u IS NULL OR NOT isfinite(u) THEN RAISE EXCEPTION 'Invalid timezone instant' USING ERRCODE='22023'; END IF;
 IF u>=c.future_start THEN RETURN system_internal.tzdb_future_v1(c.rule,u); END IF;
 SELECT offset_seconds,specified INTO result FROM system_internal.tzdb_era_v1 WHERE release_id=c.release_id AND zone_name=c.zone_name
  AND utc_start<=u AND utc_end>u ORDER BY utc_start DESC LIMIT 1;
 IF NOT FOUND THEN RAISE EXCEPTION 'Required timezone era missing' USING ERRCODE='PZ002'; END IF;
 RETURN result;
 END $f$;

CREATE FUNCTION system_internal.tzdb_resolve_v1(c system_internal.tzdb_context_v1,p_local timestamp)
 RETURNS TABLE(classification text,instant timestamptz) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $f$
 DECLARE o integer; u timestamptz; state system_internal.tzdb_state_v1; hits timestamptz[]:='{}'; unknown boolean:=false;
 BEGIN
 IF p_local IS NULL OR NOT isfinite(p_local) OR p_local<timestamp '0001-01-01' OR p_local>=timestamp '10000-01-01' THEN
  RAISE EXCEPTION 'Unsupported recurring local date' USING ERRCODE='22023'; END IF;
 FOREACH o IN ARRAY c.offsets LOOP
  u:=(p_local AT TIME ZONE INTERVAL '0')-o*interval '1 second'; state:=system_internal.tzdb_offset_at_v1(c,u);
  IF NOT state.specified THEN unknown:=true;
  ELSIF state.offset_seconds=o AND NOT u=ANY(hits) THEN hits:=array_append(hits,u); END IF;
 END LOOP;
 IF unknown THEN RETURN QUERY SELECT 'unsupported_timezone_semantics'::text,NULL::timestamptz;
 ELSIF cardinality(hits)=0 THEN RETURN QUERY SELECT 'nonexistent_local_time'::text,NULL::timestamptz;
 ELSIF cardinality(hits)>1 THEN RETURN QUERY SELECT 'ambiguous_local_time'::text,NULL::timestamptz;
 ELSE RETURN QUERY SELECT 'unique'::text,hits[1]; END IF;
 END $f$;

CREATE FUNCTION system_internal.tzdb_immutable_v1() RETURNS trigger
 LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $f$
 DECLARE z text;
 BEGIN
 IF TG_OP='INSERT' THEN
  IF TG_TABLE_NAME='tzdb_release_v1' THEN
   IF NEW.sealed THEN RAISE EXCEPTION 'Release must be validated before sealing' USING ERRCODE='23514'; END IF;
  END IF;
  IF TG_TABLE_NAME<>'tzdb_release_v1' AND EXISTS(SELECT 1 FROM system_internal.tzdb_release_v1 WHERE release_id=NEW.release_id AND sealed) THEN
   RAISE EXCEPTION 'Sealed timezone release is immutable' USING ERRCODE='23514'; END IF; RETURN NEW;
 END IF;
 IF TG_TABLE_NAME='tzdb_release_v1' AND TG_OP='UPDATE' THEN
  IF NOT OLD.sealed AND NEW.sealed AND (OLD.release_id,OLD.identity,OLD.created_at) IS NOT DISTINCT FROM (NEW.release_id,NEW.identity,NEW.created_at) THEN
   PERFORM system_internal.tzdb_check_release_v1(NEW.release_id);
   FOR z IN SELECT zone_name FROM system_internal.tzdb_zone_v1 WHERE release_id=NEW.release_id LOOP
    PERFORM system_internal.tzdb_context_v1(NEW.release_id,z);
   END LOOP;
   RETURN NEW;
  END IF;
 END IF;
 RAISE EXCEPTION 'Timezone reference data is immutable' USING ERRCODE='23514';
 END $f$;

CREATE FUNCTION system_internal.tzdb_activate_v1() RETURNS trigger
 LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $f$
 BEGIN
 IF NOT EXISTS(SELECT 1 FROM system_internal.tzdb_release_v1 WHERE release_id=NEW.release_id AND sealed) THEN
  RAISE EXCEPTION 'Unsealed timezone release cannot activate' USING ERRCODE='PZ002'; END IF;
 PERFORM system_internal.tzdb_check_release_v1(NEW.release_id); RETURN NEW;
 END $f$;
CREATE TRIGGER validate_active_release BEFORE INSERT OR UPDATE ON system_internal.tzdb_active_v1
 FOR EACH ROW EXECUTE FUNCTION system_internal.tzdb_activate_v1();

DO $security$
DECLARE t text; f regprocedure;
BEGIN
 FOREACH t IN ARRAY ARRAY['tzdb_release_v1','tzdb_active_v1','tzdb_zone_v1','tzdb_offset_v1','tzdb_era_v1','tzdb_rule_v1'] LOOP
  EXECUTE format('ALTER TABLE system_internal.%I OWNER TO %I',t,current_user);
  EXECUTE format('ALTER TABLE system_internal.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('REVOKE ALL ON system_internal.%I FROM PUBLIC,anon,authenticated,service_role,quest_command_owner',t);
  IF t<>'tzdb_active_v1' THEN
   EXECUTE format('CREATE TRIGGER immutable_rows BEFORE INSERT OR UPDATE OR DELETE ON system_internal.%I FOR EACH ROW EXECUTE FUNCTION system_internal.tzdb_immutable_v1()',t);
   EXECUTE format('CREATE TRIGGER immutable_truncate BEFORE TRUNCATE ON system_internal.%I FOR EACH STATEMENT EXECUTE FUNCTION system_internal.tzdb_immutable_v1()',t);
  END IF;
 END LOOP;
 FOR f IN SELECT oid::regprocedure FROM pg_proc WHERE pronamespace='system_internal'::regnamespace AND proname LIKE 'tzdb_%' LOOP
  EXECUTE format('ALTER FUNCTION %s OWNER TO %I',f,current_user);
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,service_role,quest_command_owner',f);
 END LOOP;
END $security$;
GRANT EXECUTE ON FUNCTION system_internal.tzdb_active_release_v1(),system_internal.tzdb_context_v1(text,text),
 system_internal.tzdb_offset_at_v1(system_internal.tzdb_context_v1,timestamptz),system_internal.tzdb_resolve_v1(system_internal.tzdb_context_v1,timestamp)
 TO quest_command_owner;

UPDATE system_internal.tzdb_release_v1 SET sealed=true WHERE release_id='system-tz-v1/3266c359c01310e23422e0b6cc5bcb849ab6b3f413f4e3a1da5b8a0a40894d98';
-- END GENERATED TIMEZONE CATALOG V1

DO $preflight$
BEGIN
    IF EXISTS (SELECT 1 FROM public.quest_recurrence_rules WHERE local_start_time IS NOT NULL) THEN
        RAISE EXCEPTION 'Recurring schedule defaults require a reviewed preflight: dormant non-null local_start_time exists; no data was changed'
            USING ERRCODE = '23514';
    END IF;
END;
$preflight$;
ALTER TABLE public.quest_recurrence_rules ADD COLUMN local_end_time time without time zone;
ALTER TABLE public.quest_recurrence_rules ADD COLUMN planned_end_day_offset smallint;
ALTER TABLE public.quest_recurrence_rules ADD CONSTRAINT ck_rule_schedule_tuple CHECK (
    num_nonnulls(local_start_time,local_end_time,planned_end_day_offset) IN (0,3)
);
ALTER TABLE public.quest_recurrence_rules ADD CONSTRAINT ck_rule_schedule_precision CHECK (
    (local_start_time IS NULL OR (local_start_time < time '24:00' AND extract(second FROM local_start_time)=0))
    AND (local_end_time IS NULL OR (local_end_time < time '24:00' AND extract(second FROM local_end_time)=0))
);
ALTER TABLE public.quest_recurrence_rules ADD CONSTRAINT ck_rule_schedule_interval CHECK (
    planned_end_day_offset IS NULL OR
    (planned_end_day_offset=0 AND local_end_time>local_start_time) OR
    (planned_end_day_offset=1 AND local_end_time<=local_start_time)
);

CREATE FUNCTION system_internal.valid_recurring_schedule_v1(a time,b time,d smallint)
RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $function$
    SELECT num_nonnulls(a,b,d)=0 OR coalesce(num_nonnulls(a,b,d)=3
        AND a<time '24:00' AND b<time '24:00'
        AND extract(second FROM a)=0 AND extract(second FROM b)=0
        AND ((d=0 AND b>a) OR (d=1 AND b<=a)),false);
$function$;

-- Standalone private resolver validates context; batches validate it only once.
CREATE FUNCTION system_internal.resolve_recurring_local_v1(p_local timestamp,p_zone text)
RETURNS TABLE(classification text,instant timestamptz)
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $function$
DECLARE release text; context system_internal.tzdb_context_v1;
BEGIN
 IF p_zone IS NULL THEN RAISE EXCEPTION 'Profile timezone is required' USING ERRCODE='PZ001'; END IF;
 release:=system_internal.tzdb_active_release_v1();
 context:=system_internal.tzdb_context_v1(release,p_zone);
 RETURN QUERY SELECT * FROM system_internal.tzdb_resolve_v1(context,p_local);
END;
$function$;

ALTER TABLE public.quest_occurrences ADD COLUMN source_tzdb_release_id text NULL
 REFERENCES system_internal.tzdb_release_v1(release_id);
ALTER TABLE public.quest_occurrences ADD CONSTRAINT ck_occurrence_tzdb_source
 CHECK(source_tzdb_release_id IS NULL OR recurrence_rule_id IS NOT NULL);
COMMENT ON COLUMN public.quest_occurrences.source_tzdb_release_id IS
 'Immutable SYSTEM timezone release used at recurring materialization, including eligibility; legacy/one-off NULL.';
CREATE FUNCTION system_internal.preserve_occurrence_tzdb_v1() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog AS $function$
BEGIN
 IF NEW.source_tzdb_release_id IS DISTINCT FROM OLD.source_tzdb_release_id THEN
  RAISE EXCEPTION 'Occurrence timezone provenance is immutable' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$;
REVOKE ALL ON FUNCTION system_internal.preserve_occurrence_tzdb_v1() FROM PUBLIC,anon,authenticated,service_role,quest_command_owner;
CREATE TRIGGER preserve_occurrence_tzdb BEFORE UPDATE ON public.quest_occurrences
 FOR EACH ROW EXECUTE FUNCTION system_internal.preserve_occurrence_tzdb_v1();

CREATE FUNCTION system_internal.recurring_rule_snapshot_v1(r public.quest_recurrence_rules)
RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $function$
    SELECT jsonb_build_object('recurrence_type',r.recurrence_type,'interval_count',r.interval_count,
        'weekdays',r.weekdays,'month_day',r.month_day,'anchor_date',r.anchor_date,'end_date',r.end_date,
        'occurrence_limit',r.occurrence_limit,'revision',r.revision,'stopped_at',r.stopped_at,
        'local_start_time',CASE WHEN r.local_start_time IS NOT NULL THEN to_char(date '2000-01-01'+r.local_start_time,'HH24:MI') END,
        'local_end_time',CASE WHEN r.local_end_time IS NOT NULL THEN to_char(date '2000-01-01'+r.local_end_time,'HH24:MI') END,
        'planned_end_day_offset',r.planned_end_day_offset);
$function$;

CREATE FUNCTION system_internal.materialize_quest_day_v2(p_day date)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $function$
DECLARE actor uuid; zone text; evaluated timestamptz; selected_day date; today_local date;
    q public.quests; r public.quest_recurrence_rules; count_created integer:=0; inserted integer;
    a record; b record; start_at timestamptz; end_at timestamptz; issues jsonb:='[]'; issue jsonb;
    release text; context system_internal.tzdb_context_v1; current_state system_internal.tzdb_state_v1;
BEGIN
    PERFORM system_private.require_owner();
    actor:=system_internal.request_user_id();
    IF actor IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
    PERFORM progression_internal.lock_owner(actor);
    evaluated:=clock_timestamp();
    SELECT p.timezone INTO zone FROM public.profiles p WHERE p.user_id=actor;
    IF zone IS NULL THEN RAISE EXCEPTION 'Profile timezone is required' USING ERRCODE='PZ001'; END IF;
    release:=system_internal.tzdb_active_release_v1();
    context:=system_internal.tzdb_context_v1(release,zone);
    current_state:=system_internal.tzdb_offset_at_v1(context,evaluated);
    IF current_state.specified THEN
        today_local:=((evaluated AT TIME ZONE INTERVAL '0')+current_state.offset_seconds*interval '1 second')::date;
    END IF;
    selected_day:=coalesce(p_day,today_local);
    IF NOT isfinite(selected_day) OR selected_day<date '0001-01-01' OR selected_day>date '9999-12-31' THEN
        RAISE EXCEPTION 'Invalid recurring date' USING ERRCODE='22023';
    END IF;
    FOR q IN SELECT * FROM public.quests WHERE user_id=actor AND archived_at IS NULL
        AND deleted_at IS NULL AND recurrence_mode IN ('daily','weekly','monthly') ORDER BY id FOR UPDATE
    LOOP
        SELECT * INTO r FROM public.quest_recurrence_rules WHERE quest_id=q.id AND user_id=actor FOR UPDATE;
        IF NOT FOUND OR r.stopped_at IS NOT NULL THEN CONTINUE; END IF;
        IF today_local IS NULL THEN
            issues:=issues||jsonb_build_array(jsonb_build_object('quest_id',q.id,'recurrence_rule_id',r.id,
                'rule_revision',r.revision,'source_slot_date',selected_day,'local_start_time',r.local_start_time,
                'local_end_time',r.local_end_time,'planned_end_day_offset',r.planned_end_day_offset,
                'endpoint','interval','reason','unsupported_timezone_semantics')); CONTINUE;
        END IF;
        IF selected_day<today_local OR selected_day<r.anchor_date
            OR (r.end_date IS NOT NULL AND selected_day>r.end_date)
            OR (r.occurrence_limit IS NOT NULL AND q.materialized_occurrence_count>=r.occurrence_limit) THEN CONTINUE; END IF;
        IF NOT (r.recurrence_type='daily'
            OR (r.recurrence_type='selected_weekdays' AND extract(isodow FROM selected_day)::smallint=ANY(r.weekdays))
            OR (r.recurrence_type='monthly' AND extract(day FROM selected_day)=least(r.month_day,
                extract(day FROM date_trunc('month',selected_day)+interval '1 month - 1 day')))) THEN CONTINUE; END IF;
        -- Retained identity wins BEFORE interpreting mutable current defaults.
        IF EXISTS(SELECT 1 FROM public.quest_occurrences WHERE quest_id=q.id AND user_id=actor
            AND source_slot_date=selected_day AND recurrence_rule_id IS NOT NULL) THEN CONTINUE; END IF;
        start_at:=NULL; end_at:=NULL;
        IF r.local_start_time IS NOT NULL THEN
            issue:=jsonb_build_object('quest_id',q.id,'recurrence_rule_id',r.id,'rule_revision',r.revision,
                'source_slot_date',selected_day,'local_start_time',to_char(date '2000-01-01'+r.local_start_time,'HH24:MI'),
                'local_end_time',to_char(date '2000-01-01'+r.local_end_time,'HH24:MI'),'planned_end_day_offset',r.planned_end_day_offset);
            IF selected_day+r.planned_end_day_offset>date '9999-12-31' THEN
                issues:=issues||jsonb_build_array(issue||jsonb_build_object('endpoint','interval','reason','invalid_interval')); CONTINUE;
            END IF;
            SELECT * INTO a FROM system_internal.tzdb_resolve_v1(context,selected_day+r.local_start_time);
            SELECT * INTO b FROM system_internal.tzdb_resolve_v1(context,(selected_day+r.planned_end_day_offset)+r.local_end_time);
            IF a.classification<>'unique' OR b.classification<>'unique' THEN
                IF a.classification<>'unique' THEN issues:=issues||jsonb_build_array(issue||jsonb_build_object('endpoint','start','reason',a.classification)); END IF;
                IF b.classification<>'unique' THEN issues:=issues||jsonb_build_array(issue||jsonb_build_object('endpoint','end','reason',b.classification)); END IF;
                CONTINUE;
            END IF;
            IF a.instant<timestamptz '0001-01-01Z' OR a.instant>=timestamptz '10000-01-01Z'
                OR b.instant<timestamptz '0001-01-01Z' OR b.instant>=timestamptz '10000-01-01Z' THEN
                issues:=issues||jsonb_build_array(issue||jsonb_build_object('endpoint','interval','reason','unsupported_instant_range')); CONTINUE;
            END IF;
            start_at:=a.instant; end_at:=b.instant;
            IF end_at<=start_at OR NOT isfinite(start_at) OR NOT isfinite(end_at) THEN
                issues:=issues||jsonb_build_array(issue||jsonb_build_object('endpoint','interval','reason','invalid_interval')); CONTINUE;
            END IF;
        END IF;
            reward_exp_snapshot,difficulty_snapshot,estimated_duration_minutes_snapshot,energy_cost_snapshot,
            focus_demand_snapshot,recurrence_rule_id,recurrence_revision,source_slot_date,source_timezone,source_tzdb_release_id,
            direct_goal_id_snapshot,project_id_snapshot,penalty_snapshot,execution_cycle)
        VALUES(q.id,actor,CASE WHEN start_at IS NULL THEN 'draft' ELSE 'scheduled' END,start_at,end_at,NULL,
            coalesce(q.default_reward_exp,0),q.default_difficulty,q.default_estimated_duration_minutes,q.default_energy_cost,
            q.default_focus_demand,r.id,r.revision,selected_day,zone,release,NULL,NULL,NULL,1)
        ON CONFLICT(quest_id,source_slot_date) WHERE recurrence_rule_id IS NOT NULL DO NOTHING;
        GET DIAGNOSTICS inserted=ROW_COUNT;
        IF inserted=1 THEN
            UPDATE public.quests SET materialized_occurrence_count=materialized_occurrence_count+1,updated_at=evaluated WHERE id=q.id AND user_id=actor;
            count_created:=count_created+1;
        END IF;
    END LOOP;
    RETURN jsonb_build_object('version',2,'day',selected_day,'timezone',zone,'created_count',count_created,'issues',issues);
END;
$function$;

GRANT quest_command_owner TO CURRENT_USER;
GRANT CREATE ON SCHEMA public TO quest_command_owner;

CREATE OR REPLACE FUNCTION public.materialize_quest_day(p_day date DEFAULT NULL)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $function$
BEGIN
    PERFORM system_private.require_owner();
    RETURN (system_internal.materialize_quest_day_v2(p_day)->>'created_count')::integer;
END;
$function$;
CREATE FUNCTION public.materialize_quest_day_v2(p_day date DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $function$
BEGIN
    PERFORM system_private.require_owner();
    RETURN system_internal.materialize_quest_day_v2(p_day);
END;
$function$;

CREATE FUNCTION public.get_recurring_quest_detail_v1(p_quest_id uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $function$
DECLARE actor uuid; result jsonb;
BEGIN
    PERFORM system_private.require_owner();
    actor:=system_internal.request_user_id();
    IF actor IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
    SELECT jsonb_build_object('version',1,'quest_id',q.id,'title',q.title,'recurrence_mode',q.recurrence_mode,
        'recurrence_rule_id',r.id,'rule',jsonb_build_object('recurrence_type',r.recurrence_type,'interval_count',r.interval_count,
            'weekdays',r.weekdays,'month_day',r.month_day,'anchor_date',r.anchor_date,'end_date',r.end_date,
            'occurrence_limit',r.occurrence_limit,'revision',r.revision,'stopped_at',r.stopped_at,
            'local_start_time',CASE WHEN r.local_start_time IS NOT NULL THEN to_char(date '2000-01-01'+r.local_start_time,'HH24:MI') END,
            'local_end_time',CASE WHEN r.local_end_time IS NOT NULL THEN to_char(date '2000-01-01'+r.local_end_time,'HH24:MI') END,
            'planned_end_day_offset',r.planned_end_day_offset),
        'paused',r.stopped_at IS NOT NULL,'materialized_occurrence_count',q.materialized_occurrence_count,
        'timezone',p.timezone) INTO result
    FROM public.quests q JOIN public.quest_recurrence_rules r ON r.quest_id=q.id AND r.user_id=actor
    JOIN public.profiles p ON p.user_id=actor WHERE q.id=p_quest_id AND q.user_id=actor
        AND q.archived_at IS NULL AND q.deleted_at IS NULL AND q.recurrence_mode IN ('daily','weekly','monthly');
    RETURN result;
END;
$function$;

CREATE FUNCTION public.set_recurring_quest_schedule_defaults_v1(
    p_command_id uuid,p_quest_id uuid,p_expected_rule_revision integer,
    p_local_start_time time without time zone,p_local_end_time time without time zone,
    p_planned_end_day_offset smallint,p_origin text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $function$
DECLARE actor uuid; q public.quests; r public.quest_recurrence_rules; prior public.quest_events;
    request jsonb; receipt jsonb; before_rule jsonb; after_rule jsonb; changed boolean;
    event_id uuid; effective timestamptz; event_count bigint;
BEGIN
    PERFORM system_private.require_owner(); actor:=system_internal.request_user_id();
    IF actor IS NULL OR p_command_id IS NULL OR p_quest_id IS NULL THEN RAISE EXCEPTION 'Command identity required' USING ERRCODE='42501'; END IF;
    PERFORM progression_internal.require_origin(p_origin);
    IF p_expected_rule_revision IS NULL OR p_expected_rule_revision<1
        OR NOT system_internal.valid_recurring_schedule_v1(p_local_start_time,p_local_end_time,p_planned_end_day_offset) THEN
        RAISE EXCEPTION 'Invalid recurring schedule defaults' USING ERRCODE='22023';
    END IF;
    request:=jsonb_build_object('quest_id',p_quest_id,'expected_rule_revision',p_expected_rule_revision,
        'local_start_time',CASE WHEN p_local_start_time IS NOT NULL THEN to_char(date '2000-01-01'+p_local_start_time,'HH24:MI') END,
        'local_end_time',CASE WHEN p_local_end_time IS NOT NULL THEN to_char(date '2000-01-01'+p_local_end_time,'HH24:MI') END,
        'planned_end_day_offset',p_planned_end_day_offset,'origin',p_origin);
    PERFORM progression_internal.lock_owner(actor);
    PERFORM system_internal.reject_completion_alias(p_command_id);
    SELECT * INTO q FROM public.quests WHERE id=p_quest_id AND user_id=actor FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Recurring Quest not found' USING ERRCODE='P0002'; END IF;
    SELECT * INTO r FROM public.quest_recurrence_rules WHERE quest_id=q.id AND user_id=actor FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Recurring rule not found' USING ERRCODE='23514'; END IF;
    SELECT count(*) INTO event_count FROM public.quest_events WHERE user_id=actor AND command_id=p_command_id;
    IF event_count>0 THEN
        SELECT * INTO prior FROM public.quest_events WHERE user_id=actor AND command_id=p_command_id
            AND quest_id=q.id AND event_type='recurrence_changed' AND occurrence_id IS NULL;
        IF event_count<>1 OR NOT FOUND OR prior.execution_cycle IS NOT NULL OR prior.actor_kind<>'user'
            OR prior.actor_user_id IS DISTINCT FROM actor OR prior.payload_version<>1
            OR prior.payload->>'command_kind' IS DISTINCT FROM 'recurring_schedule_defaults_v1'
            OR prior.payload->'request' IS DISTINCT FROM request THEN
            RAISE EXCEPTION 'Conflicting schedule defaults command reuse' USING ERRCODE='23505';
        END IF;
        RETURN (prior.payload->'receipt')||jsonb_build_object('replay',true);
    END IF;
    IF q.archived_at IS NOT NULL OR q.deleted_at IS NOT NULL OR q.recurrence_mode NOT IN ('daily','weekly','monthly')
        OR r.recurrence_type NOT IN ('daily','selected_weekdays','monthly') THEN
        RAISE EXCEPTION 'Recurring Quest is not editable' USING ERRCODE='23514';
    END IF;
    IF r.revision<>p_expected_rule_revision THEN RAISE EXCEPTION 'Stale recurring rule revision' USING ERRCODE='23514'; END IF;
    before_rule:=system_internal.recurring_rule_snapshot_v1(r);
    changed:=ROW(r.local_start_time,r.local_end_time,r.planned_end_day_offset) IS DISTINCT FROM ROW(p_local_start_time,p_local_end_time,p_planned_end_day_offset);
    effective:=clock_timestamp(); event_id:=gen_random_uuid();
    IF changed THEN
        r.local_start_time:=p_local_start_time; r.local_end_time:=p_local_end_time; r.planned_end_day_offset:=p_planned_end_day_offset;
        r.revision:=r.revision+1;
        UPDATE public.quest_recurrence_rules SET local_start_time=r.local_start_time,local_end_time=r.local_end_time,
            planned_end_day_offset=r.planned_end_day_offset,revision=r.revision,updated_at=effective WHERE id=r.id AND user_id=actor;
    END IF;
    after_rule:=system_internal.recurring_rule_snapshot_v1(r);
    receipt:=jsonb_build_object('version',1,'command_id',p_command_id,'quest_id',q.id,'recurrence_rule_id',r.id,
        'event_id',event_id,'before',before_rule,'after',after_rule,'changed',changed,'effective_at',effective,'replay',false);
    VALUES(event_id,q.id,actor,'recurrence_changed','user',actor,effective,p_command_id,1,
        jsonb_build_object('command_kind','recurring_schedule_defaults_v1','request',request,'before',before_rule,'after',after_rule,'receipt',receipt));
    RETURN receipt;
END;
$function$;


CREATE FUNCTION system_internal.create_recurring_quest_v2(
    command_id uuid,
    request jsonb,
    origin text,
    contract_version integer
) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog
AS $function$
DECLARE
    actor uuid;
    v_start time; v_finish time; v_offset smallint; receipt jsonb;
    profile_timezone text;
    definition jsonb;
    rule jsonb;
    prior_created public.quest_events;
    prior_changed public.quest_events;
    prior_rule public.quest_recurrence_rules;
    event_count integer;
    quest_id uuid;
    rule_id uuid;
    created_event_id uuid;
    changed_event_id uuid;
    v_now timestamptz;
    v_title text;
    v_description text;
    v_importance text := 'side';
    v_priority text;
    v_difficulty smallint;
    v_duration integer;
    v_energy smallint;
    v_focus smallint;
    v_reward integer;
    v_tags text[] := ARRAY[]::text[];
    v_notes text;
    v_mode text;
    v_type text;
    v_anchor date;
    v_end_date date;
    v_weekdays smallint[];
    v_month_day smallint;
    v_limit integer;
    key_name text;
    number_value numeric;
BEGIN
    PERFORM system_private.require_owner();
    actor := system_internal.request_user_id();
    IF actor IS NULL OR command_id IS NULL OR request IS NULL
        OR jsonb_typeof(request) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'Authentication and required creation inputs are mandatory'
            USING ERRCODE = '42501';
    END IF;
    PERFORM progression_internal.require_origin(origin);

    -- The request surface is deliberately closed. In particular Goal, Project, Penalty,
    -- absolute one-off instants and unknown inputs fail loudly instead of disappearing.
    IF EXISTS (
        SELECT 1 FROM jsonb_object_keys(request) AS supplied(key)
        WHERE supplied.key NOT IN ('title', 'description', 'importance',
            'priority', 'default_difficulty', 'default_estimated_duration_minutes',
            'default_energy_cost', 'default_focus_demand', 'default_reward_exp',
            'tags', 'notes', 'recurrence_mode', 'start_date', 'end_date',
            'weekdays', 'month_day', 'occurrence_limit')
            AND NOT (contract_version=2 AND supplied.key IN ('local_start_time','local_end_time','planned_end_day_offset'))
    ) THEN
        RAISE EXCEPTION 'Unsupported recurring Quest input (Goal, Project, Penalty, one-off instants and unknown inputs are unavailable)'
            USING ERRCODE = '22023';
    END IF;

    IF jsonb_typeof(request -> 'recurrence_mode') IS DISTINCT FROM 'string'
        OR (request ->> 'recurrence_mode') NOT IN ('daily', 'weekly', 'monthly') THEN
        RAISE EXCEPTION 'recurrence_mode must be daily, weekly or monthly' USING ERRCODE = '22023';
    END IF;
    v_mode := request ->> 'recurrence_mode';
    -- The Quest-level cadence and the rule-level discriminator are separate stored
    -- dimensions: weekly cadence is the already-constrained 'selected_weekdays' rule.
    v_type := CASE v_mode WHEN 'daily' THEN 'daily'
        WHEN 'weekly' THEN 'selected_weekdays' ELSE 'monthly' END;

    IF jsonb_typeof(request -> 'title') IS DISTINCT FROM 'string'
        OR btrim(request ->> 'title') = '' THEN
        RAISE EXCEPTION 'title is required and must be nonblank' USING ERRCODE = '22023';
    END IF;
    v_title := request ->> 'title';
    IF char_length(v_title) > 120 THEN
        RAISE EXCEPTION 'title is too long' USING ERRCODE = '22023';
    END IF;

    IF request ? 'description' AND jsonb_typeof(request -> 'description') NOT IN ('string', 'null') THEN
        RAISE EXCEPTION 'description must be text or null' USING ERRCODE = '22023';
    END IF;
    v_description := request ->> 'description';
    IF char_length(v_description) > 4000 THEN
        RAISE EXCEPTION 'description is too long' USING ERRCODE = '22023';
    END IF;

    FOREACH key_name IN ARRAY ARRAY['importance', 'priority'] LOOP
        IF request ? key_name AND jsonb_typeof(request -> key_name) NOT IN ('string', 'null') THEN
            RAISE EXCEPTION '% must be text or null', key_name USING ERRCODE = '22023';
        END IF;
    END LOOP;
    IF request ? 'importance' AND request ->> 'importance' IS NOT NULL THEN
        v_importance := request ->> 'importance';
    END IF;
    v_priority := request ->> 'priority';
    IF v_importance NOT IN ('main', 'side')
        OR (v_priority IS NOT NULL AND v_priority NOT IN ('low', 'medium', 'high', 'critical')) THEN
        RAISE EXCEPTION 'Invalid importance or priority' USING ERRCODE = '22023';
    END IF;

    FOREACH key_name IN ARRAY ARRAY['default_difficulty', 'default_estimated_duration_minutes',
        'default_energy_cost', 'default_focus_demand', 'default_reward_exp'] LOOP
        IF request ? key_name AND jsonb_typeof(request -> key_name) NOT IN ('number', 'null') THEN
            RAISE EXCEPTION '% must be an integer or null', key_name USING ERRCODE = '22023';
        END IF;
        IF request ? key_name AND jsonb_typeof(request -> key_name) = 'number' THEN
            number_value := (request ->> key_name)::numeric;
            IF number_value <> trunc(number_value) THEN
                RAISE EXCEPTION '% must be an integer', key_name USING ERRCODE = '22023';
            END IF;
            IF (key_name IN ('default_difficulty', 'default_energy_cost', 'default_focus_demand')
                    AND number_value NOT BETWEEN -32768 AND 32767)
                OR (key_name IN ('default_estimated_duration_minutes', 'default_reward_exp')
                    AND number_value NOT BETWEEN -2147483648 AND 2147483647) THEN
                RAISE EXCEPTION '% is outside its PostgreSQL integer range', key_name
                    USING ERRCODE = '22003';
            END IF;
        END IF;
    END LOOP;
    v_difficulty := (request ->> 'default_difficulty')::smallint;
    v_duration := (request ->> 'default_estimated_duration_minutes')::integer;
    v_energy := (request ->> 'default_energy_cost')::smallint;
    v_focus := (request ->> 'default_focus_demand')::smallint;
    v_reward := COALESCE((request ->> 'default_reward_exp')::integer, 0);
    IF v_difficulty IS NOT NULL AND v_difficulty NOT BETWEEN 1 AND 5
        OR v_duration IS NOT NULL AND v_duration <= 0
        OR v_energy IS NOT NULL AND v_energy NOT BETWEEN 1 AND 5
        OR v_focus IS NOT NULL AND v_focus NOT BETWEEN 1 AND 5
        OR v_reward < 0 THEN
        RAISE EXCEPTION 'Invalid Quest numeric value' USING ERRCODE = '22023';
    END IF;

    IF request ? 'tags' AND jsonb_typeof(request -> 'tags') NOT IN ('array', 'null') THEN
        RAISE EXCEPTION 'tags must be an array or null' USING ERRCODE = '22023';
    END IF;
    IF request ? 'tags' AND jsonb_typeof(request -> 'tags') = 'array' THEN
        IF EXISTS (SELECT 1 FROM jsonb_array_elements(request -> 'tags') AS item
            WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'string') THEN
            RAISE EXCEPTION 'tags must contain only text values' USING ERRCODE = '22023';
        END IF;
        SELECT COALESCE(array_agg(item.value #>> '{}' ORDER BY item.ordinality), ARRAY[]::text[])
            INTO v_tags
            FROM jsonb_array_elements(request -> 'tags') WITH ORDINALITY AS item(value, ordinality);
    END IF;
    IF request ? 'notes' AND jsonb_typeof(request -> 'notes') NOT IN ('string', 'null') THEN
        RAISE EXCEPTION 'notes must be text or null' USING ERRCODE = '22023';
    END IF;
    v_notes := request ->> 'notes';
    IF char_length(v_notes) > 4000 THEN
        RAISE EXCEPTION 'notes is too long' USING ERRCODE = '22023';
    END IF;

    -- RR-02/RR-03: the schedule is profile-local calendar data, never an absolute
    -- instant. start_date is the inclusive anchor; end_date is inclusive when supplied.
    IF jsonb_typeof(request -> 'start_date') IS DISTINCT FROM 'string'
        OR (request ->> 'start_date') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
        RAISE EXCEPTION 'start_date is required and must be a YYYY-MM-DD calendar date' USING ERRCODE = '22023';
    END IF;
    BEGIN
        v_anchor := (request ->> 'start_date')::date;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'start_date is not a valid calendar date' USING ERRCODE = '22023';
    END;
    IF request ? 'end_date' AND jsonb_typeof(request -> 'end_date') NOT IN ('string', 'null') THEN
        RAISE EXCEPTION 'end_date must be a YYYY-MM-DD calendar date or null' USING ERRCODE = '22023';
    END IF;
    IF request ? 'end_date' AND jsonb_typeof(request -> 'end_date') = 'string' THEN
        IF (request ->> 'end_date') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
            RAISE EXCEPTION 'end_date must be a YYYY-MM-DD calendar date or null' USING ERRCODE = '22023';
        END IF;
        BEGIN
            v_end_date := (request ->> 'end_date')::date;
        EXCEPTION WHEN OTHERS THEN
            RAISE EXCEPTION 'end_date is not a valid calendar date' USING ERRCODE = '22023';
        END;
        IF v_end_date < v_anchor THEN
            RAISE EXCEPTION 'end_date must not precede start_date' USING ERRCODE = '22023';
        END IF;
    END IF;

    -- Cadence parameters are strictly discriminator-bound, mirroring ck_rule_weekdays
    -- and ck_rule_month_day so a mismatched parameter can never be silently dropped.
    IF v_mode = 'weekly' THEN
        IF jsonb_typeof(request -> 'weekdays') IS DISTINCT FROM 'array'
            OR jsonb_array_length(request -> 'weekdays') NOT BETWEEN 1 AND 7 THEN
            RAISE EXCEPTION 'weekdays is required for a weekly Quest and must hold 1 to 7 ISO weekdays' USING ERRCODE = '22023';
        END IF;
        IF EXISTS (SELECT 1 FROM jsonb_array_elements(request -> 'weekdays') AS item
            WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'number') THEN
            RAISE EXCEPTION 'weekdays must contain only whole numbers' USING ERRCODE = '22023';
        END IF;
        IF EXISTS (SELECT 1 FROM jsonb_array_elements(request -> 'weekdays') AS item
            WHERE (item.value #>> '{}')::numeric <> trunc((item.value #>> '{}')::numeric)) THEN
            RAISE EXCEPTION 'weekdays must contain only whole numbers' USING ERRCODE = '22023';
        END IF;
        SELECT array_agg(DISTINCT (item.value #>> '{}')::smallint
                ORDER BY (item.value #>> '{}')::smallint)
            INTO v_weekdays
            FROM jsonb_array_elements(request -> 'weekdays') AS item(value);
        IF v_weekdays IS NULL OR NOT public.quest_valid_weekdays(v_weekdays) THEN
            RAISE EXCEPTION 'weekdays must be one to seven distinct ISO weekdays from 1 (Monday) to 7 (Sunday)'
                USING ERRCODE = '22023';
        END IF;
    ELSIF request ? 'weekdays' AND jsonb_typeof(request -> 'weekdays') IS DISTINCT FROM 'null' THEN
        RAISE EXCEPTION 'weekdays is only valid for a weekly Quest' USING ERRCODE = '22023';
    END IF;

    IF v_mode = 'monthly' THEN
        IF jsonb_typeof(request -> 'month_day') IS DISTINCT FROM 'number' THEN
            RAISE EXCEPTION 'month_day is required for a monthly Quest' USING ERRCODE = '22023';
        END IF;
        number_value := (request ->> 'month_day')::numeric;
        IF number_value <> trunc(number_value) OR number_value NOT BETWEEN 1 AND 31 THEN
            RAISE EXCEPTION 'month_day must be a whole number from 1 to 31' USING ERRCODE = '22023';
        END IF;
        v_month_day := number_value::smallint;
    ELSIF request ? 'month_day' AND jsonb_typeof(request -> 'month_day') IS DISTINCT FROM 'null' THEN
        RAISE EXCEPTION 'month_day is only valid for a monthly Quest' USING ERRCODE = '22023';
    END IF;

    IF request ? 'occurrence_limit' THEN
        IF jsonb_typeof(request -> 'occurrence_limit') NOT IN ('number', 'null') THEN
            RAISE EXCEPTION 'occurrence_limit must be a positive integer or null' USING ERRCODE = '22023';
        END IF;
        IF jsonb_typeof(request -> 'occurrence_limit') = 'number' THEN
            number_value := (request ->> 'occurrence_limit')::numeric;
            IF number_value <> trunc(number_value)
                OR number_value < 1 OR number_value > 2147483647 THEN
                RAISE EXCEPTION 'occurrence_limit must be a positive integer' USING ERRCODE = '22023';
            END IF;
            v_limit := number_value::integer;
        END IF;
    END IF;

    IF contract_version NOT IN (1,2) OR contract_version IS NULL THEN
        RAISE EXCEPTION 'Unknown recurring creation contract' USING ERRCODE='22023';
    END IF;
    IF contract_version=2 THEN
        IF (request->>'local_start_time' IS NOT NULL AND (jsonb_typeof(request->'local_start_time')<>'string' OR request->>'local_start_time' !~ '^([01][0-9]|2[0-3]):[0-5][0-9](:00)?$'))
            OR (request->>'local_end_time' IS NOT NULL AND (jsonb_typeof(request->'local_end_time')<>'string' OR request->>'local_end_time' !~ '^([01][0-9]|2[0-3]):[0-5][0-9](:00)?$'))
            OR (request->>'planned_end_day_offset' IS NOT NULL AND (jsonb_typeof(request->'planned_end_day_offset')<>'number' OR (request->>'planned_end_day_offset')::numeric NOT IN (0,1))) THEN
            RAISE EXCEPTION 'Invalid schedule defaults' USING ERRCODE='22023';
        END IF;
        v_start:=(request->>'local_start_time')::time; v_finish:=(request->>'local_end_time')::time;
        v_offset:=(request->>'planned_end_day_offset')::smallint;
        IF NOT system_internal.valid_recurring_schedule_v1(v_start,v_finish,v_offset) THEN
            RAISE EXCEPTION 'Invalid schedule defaults tuple' USING ERRCODE='22023';
        END IF;
    END IF;
    definition := jsonb_build_object(
        'title', v_title, 'description', v_description, 'importance', v_importance,
        'priority', v_priority, 'default_difficulty', v_difficulty,
        'default_estimated_duration_minutes', v_duration, 'default_energy_cost', v_energy,
        'default_focus_demand', v_focus, 'default_reward_exp', v_reward,
        'direct_goal_id', NULL, 'project_id', NULL, 'recurrence_mode', v_mode,
        'default_penalty_snapshot', NULL, 'tags', to_jsonb(v_tags), 'notes', v_notes);
    rule := jsonb_build_object(
        'recurrence_type', v_type, 'interval_count', NULL,
        'weekdays', to_jsonb(v_weekdays), 'month_day', v_month_day,
        'anchor_date', v_anchor::text, 'local_start_time', NULL,
        'end_date', v_end_date::text, 'occurrence_limit', v_limit, 'revision', 1,
        'source_timezone', NULL);
    IF contract_version=2 THEN
        rule:=rule||jsonb_build_object('local_start_time',CASE WHEN v_start IS NOT NULL THEN to_char(date '2000-01-01'+v_start,'HH24:MI') END,
            'local_end_time',CASE WHEN v_finish IS NOT NULL THEN to_char(date '2000-01-01'+v_finish,'HH24:MI') END,
            'planned_end_day_offset',v_offset);
    END IF;

    -- Frozen lock order: owner-wide progression lock, then the event lookup. This is the
    -- same owner advisory lock the completion and reopen commands take, so a creation
    -- retry can never interleave with slot materialization or a completion.
    PERFORM progression_internal.lock_owner(actor);
    PERFORM system_internal.reject_completion_alias(command_id);
    SELECT count(*) INTO event_count FROM public.quest_events e
        WHERE e.user_id = actor AND e.command_id = create_recurring_quest_v2.command_id;
    IF event_count > 0 THEN
        SELECT * INTO prior_created FROM public.quest_events e
            WHERE e.user_id = actor AND e.command_id = create_recurring_quest_v2.command_id
                AND e.event_type = 'created' AND e.occurrence_id IS NULL;
        SELECT * INTO prior_changed FROM public.quest_events e
            WHERE e.user_id = actor AND e.command_id = create_recurring_quest_v2.command_id
                AND e.event_type = 'recurrence_changed' AND e.occurrence_id IS NULL;
        IF event_count <> 2 OR NOT FOUND
            OR prior_created.id IS NULL OR prior_changed.id IS NULL THEN
            RAISE EXCEPTION 'Conflicting or partial recurring Quest command reuse'
                USING ERRCODE = '23505';
        END IF;
        SELECT * INTO prior_rule FROM public.quest_recurrence_rules r
            WHERE r.quest_id = prior_changed.quest_id AND r.user_id = actor;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Conflicting or partial recurring Quest command reuse'
                USING ERRCODE = '23505';
        END IF;
        IF prior_created.user_id IS DISTINCT FROM actor
            OR prior_changed.user_id IS DISTINCT FROM actor
            OR prior_created.actor_kind IS DISTINCT FROM 'user'
            OR prior_changed.actor_kind IS DISTINCT FROM 'user'
            OR prior_created.actor_user_id IS DISTINCT FROM actor
            OR prior_changed.actor_user_id IS DISTINCT FROM actor
            OR prior_created.execution_cycle IS NOT NULL
            OR prior_changed.execution_cycle IS NOT NULL
            OR prior_created.quest_id IS DISTINCT FROM prior_changed.quest_id
            OR prior_created.payload_version IS DISTINCT FROM 1
            OR prior_changed.payload_version IS DISTINCT FROM 1
            OR jsonb_typeof(prior_created.payload) IS DISTINCT FROM 'object'
            OR (prior_created.payload - 'origin' - 'after' - CASE WHEN contract_version=2 THEN 'command_kind' ELSE '' END) <> '{}'::jsonb
            OR jsonb_typeof(prior_created.payload -> 'origin') IS DISTINCT FROM 'string'
            OR jsonb_typeof(prior_created.payload -> 'after') IS DISTINCT FROM 'object'
            OR ((prior_created.payload -> 'after') - 'definition') <> '{}'::jsonb
            OR jsonb_typeof(prior_created.payload -> 'after' -> 'definition') IS DISTINCT FROM 'object'
            OR jsonb_typeof(prior_changed.payload) IS DISTINCT FROM 'object'
            OR (prior_changed.payload - 'origin' - 'before' - 'after' - CASE WHEN contract_version=2 THEN 'command_kind' ELSE '' END - CASE WHEN contract_version=2 THEN 'receipt' ELSE '' END) <> '{}'::jsonb
            OR jsonb_typeof(prior_changed.payload -> 'origin') IS DISTINCT FROM 'string'
            OR prior_changed.payload -> 'before' IS DISTINCT FROM 'null'::jsonb
            OR jsonb_typeof(prior_changed.payload -> 'after') IS DISTINCT FROM 'object'
            OR ((prior_changed.payload -> 'after') - 'rule') <> '{}'::jsonb
            OR jsonb_typeof(prior_changed.payload -> 'after' -> 'rule') IS DISTINCT FROM 'object'
            OR prior_created.payload -> 'origin' IS DISTINCT FROM prior_changed.payload -> 'origin'
            OR prior_created.payload -> 'after' -> 'definition' IS DISTINCT FROM definition
            -- Pause state and the current Profile timezone may legitimately change
            -- after creation commits but before a lost response is recovered. Validate
            -- the recorded timezone as provenance, not as part of the caller's request.
            OR jsonb_typeof(prior_changed.payload #> '{after,rule,source_timezone}')
                IS DISTINCT FROM 'string'
            OR coalesce(prior_changed.payload #>> '{after,rule,source_timezone}','') !~ '[^[:space:]]'
            OR (contract_version=2 AND (prior_created.payload->>'command_kind' IS DISTINCT FROM 'recurring_create_v2'
                OR prior_changed.payload->>'command_kind' IS DISTINCT FROM 'recurring_create_v2'))
            OR ((prior_changed.payload -> 'after' -> 'rule') - 'source_timezone')
                IS DISTINCT FROM (rule - 'source_timezone') THEN
            RAISE EXCEPTION 'Conflicting or partial recurring Quest command reuse'
                USING ERRCODE = '23505';
        END IF;
        PERFORM progression_internal.require_origin(prior_created.payload ->> 'origin');
        PERFORM progression_internal.require_origin(prior_changed.payload ->> 'origin');
        IF contract_version=2 THEN
            receipt:=prior_changed.payload->'receipt';
            IF receipt IS DISTINCT FROM jsonb_build_object('version',2,'command_id',command_id,'quest_id',prior_changed.quest_id,
                'recurrence_rule_id',prior_rule.id,'definition_created_event_id',prior_created.id,'recurrence_changed_event_id',prior_changed.id,
                'recurrence_mode',v_mode,'recurrence_type',v_type,'anchor_date',v_anchor,'end_date',v_end_date,
                'weekdays',v_weekdays,'month_day',v_month_day,'occurrence_limit',v_limit,'default_reward_exp',v_reward,
                'revision',1,'local_start_time',rule->'local_start_time','local_end_time',rule->'local_end_time',
                'planned_end_day_offset',v_offset,'replay',false) THEN
                RAISE EXCEPTION 'Malformed creation receipt' USING ERRCODE='23505';
            END IF;
            RETURN receipt||jsonb_build_object('replay',true);
        END IF;
        RETURN to_jsonb(ROW(command_id,prior_changed.quest_id,prior_rule.id,prior_created.id,prior_changed.id,
            v_mode,v_type,v_anchor,v_end_date,v_weekdays,v_month_day,v_limit,v_reward,true)::public.quest_recurring_receipt);
    END IF;

    -- RR-03/AC-39: the authoritative zone is the Profile-owned validated IANA value.
    -- Recurrence creation is rejected, never guessed. Identical resolution to
    -- public.list_day_quest_occurrences so both day routines fail the same way.
    SELECT p.timezone INTO profile_timezone
        FROM public.profiles AS p
        WHERE p.user_id = actor;
    IF profile_timezone IS NULL THEN
        RAISE EXCEPTION 'Profile timezone is not set; complete Profile timezone setup before creating a recurring Quest'
            USING ERRCODE = 'PZ001';
    END IF;
    PERFORM system_internal.tzdb_context_v1(system_internal.tzdb_active_release_v1(),profile_timezone);

    rule:=rule||jsonb_build_object('source_timezone',profile_timezone);
    v_now := now();
    quest_id := gen_random_uuid();
    rule_id := gen_random_uuid();
    created_event_id := gen_random_uuid();
    changed_event_id := gen_random_uuid();
        default_difficulty, default_estimated_duration_minutes, default_energy_cost,
        default_focus_demand, default_reward_exp, direct_goal_id, project_id,
        recurrence_mode, default_penalty_snapshot, tags, notes, materialized_occurrence_count)
        VALUES (quest_id, actor, v_title, v_description, v_importance, v_priority,
            v_difficulty, v_duration, v_energy, v_focus, v_reward, NULL, NULL,
            v_mode, NULL, v_tags, v_notes, 0);
        interval_count, weekdays, month_day, anchor_date, local_start_time, end_date,
        occurrence_limit, revision, stopped_at, local_end_time, planned_end_day_offset)
        VALUES (rule_id, quest_id, actor, v_type, NULL, v_weekdays, v_month_day,
            v_anchor, v_start, v_end_date, v_limit, 1, NULL, v_finish, v_offset);
    receipt:=to_jsonb(ROW(command_id,quest_id,rule_id,created_event_id,changed_event_id,
        v_mode,v_type,v_anchor,v_end_date,v_weekdays,v_month_day,v_limit,v_reward,false)::public.quest_recurring_receipt);
    IF contract_version=2 THEN
        receipt:=receipt||jsonb_build_object('version',2,'revision',1,'local_start_time',rule->'local_start_time',
            'local_end_time',rule->'local_end_time','planned_end_day_offset',v_offset);
    END IF;
        actor_user_id, occurred_at, command_id, payload_version, payload)
        VALUES (created_event_id, quest_id, actor, 'created', 'user', actor, v_now,
            create_recurring_quest_v2.command_id, 1,
            jsonb_build_object('origin', origin,
                'after', jsonb_build_object('definition', definition))
                ||CASE WHEN contract_version=2 THEN jsonb_build_object('command_kind','recurring_create_v2') ELSE '{}'::jsonb END);
        actor_user_id, occurred_at, command_id, payload_version, payload)
        VALUES (changed_event_id, quest_id, actor, 'recurrence_changed', 'user', actor, v_now,
            create_recurring_quest_v2.command_id, 1,
            jsonb_build_object('origin', origin, 'before', NULL,
                'after', jsonb_build_object('rule', rule))
                ||CASE WHEN contract_version=2 THEN jsonb_build_object('command_kind','recurring_create_v2','receipt',receipt) ELSE '{}'::jsonb END);
    RETURN receipt;
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_recurring_quest(command_id uuid,request jsonb,origin text)
RETURNS public.quest_recurring_receipt LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $function$
DECLARE result public.quest_recurring_receipt;
BEGIN
    PERFORM system_private.require_owner();
    SELECT * INTO result FROM jsonb_populate_record(NULL::public.quest_recurring_receipt,
        system_internal.create_recurring_quest_v2(command_id,request,origin,1));
    RETURN result;
END;
$function$;
CREATE FUNCTION public.create_recurring_quest_v2(command_id uuid,request jsonb,origin text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $function$
BEGIN
    PERFORM system_private.require_owner();
    RETURN system_internal.create_recurring_quest_v2(command_id,request,origin,2);
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_quest_recurrence_pause(
    command_id uuid,
    quest_id uuid,
    paused boolean,
    origin text
) RETURNS public.quest_recurrence_state_receipt
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog
AS $function$
DECLARE
    actor uuid;
    definition public.quests;
    rule public.quest_recurrence_rules;
    prior public.quest_events;
    prior_rule public.quest_recurrence_rules;
    v_wanted_event text;
    v_now timestamptz;
    v_stopped_at timestamptz;
    v_event uuid;
    v_stopped_text text;
    v_previous_text text;
BEGIN
    PERFORM system_private.require_owner();
    actor := system_internal.request_user_id();
    IF actor IS NULL OR command_id IS NULL OR quest_id IS NULL OR paused IS NULL THEN
        RAISE EXCEPTION 'Authentication and required command inputs are mandatory'
            USING ERRCODE = '42501';
    END IF;
    PERFORM progression_internal.require_origin(origin);
    -- Stopping uses the dedicated recurrence_stopped kind; resuming is a rule change whose
    -- effective boundary is now, so the two actions never share a history identity.
    v_wanted_event := CASE WHEN paused THEN 'recurrence_stopped' ELSE 'recurrence_changed' END;

    PERFORM progression_internal.lock_owner(actor);
    SELECT * INTO definition FROM public.quests AS q
        WHERE q.id = set_quest_recurrence_pause.quest_id AND q.user_id = actor
        FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Unknown Quest definition' USING ERRCODE = '23514';
    END IF;
    SELECT * INTO rule FROM public.quest_recurrence_rules AS r
        WHERE r.quest_id = definition.id AND r.user_id = actor;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Unknown recurring Quest definition' USING ERRCODE = '23514';
    END IF;
    IF definition.recurrence_mode = 'one_off' THEN
        RAISE EXCEPTION 'A one-off Quest has no recurrence to change' USING ERRCODE = '23514';
    END IF;

    -- An accepted command identity is replayable and returns its recorded receipt; it can
    -- never write a second history row (uq_definition_command_effect is the backstop).
    SELECT * INTO prior FROM public.quest_events AS e
        WHERE e.user_id = actor
            AND e.command_id = set_quest_recurrence_pause.command_id
            AND e.occurrence_id IS NULL
            AND e.event_type IN ('recurrence_changed', 'recurrence_stopped');
    IF FOUND THEN
        SELECT * INTO prior_rule FROM public.quest_recurrence_rules AS r
            WHERE r.quest_id = prior.quest_id AND r.user_id = actor;
        IF NOT FOUND OR prior.quest_id IS DISTINCT FROM definition.id
            OR prior.actor_kind IS DISTINCT FROM 'user'
            OR prior.actor_user_id IS DISTINCT FROM actor
            OR prior.execution_cycle IS NOT NULL
            OR prior.event_type IS DISTINCT FROM v_wanted_event
            OR prior.payload_version IS DISTINCT FROM 1
            OR jsonb_typeof(prior.payload) IS DISTINCT FROM 'object'
            OR (prior.payload - 'origin' - 'before' - 'after') <> '{}'::jsonb
            OR jsonb_typeof(prior.payload -> 'origin') IS DISTINCT FROM 'string'
            OR jsonb_typeof(prior.payload -> 'before') IS DISTINCT FROM 'object'
            OR jsonb_typeof(prior.payload -> 'after') IS DISTINCT FROM 'object'
            OR jsonb_typeof(prior.payload #> '{before,rule}') IS DISTINCT FROM 'object'
            OR jsonb_typeof(prior.payload #> '{after,rule}') IS DISTINCT FROM 'object'
            OR ((prior.payload -> 'before' -> 'rule') - 'stopped' - 'stopped_at')
                IS DISTINCT FROM '{}'::jsonb
            OR ((prior.payload -> 'after' -> 'rule') - 'stopped' - 'stopped_at')
                IS DISTINCT FROM '{}'::jsonb
            OR prior.payload #> '{before,rule,stopped}' IS DISTINCT FROM to_jsonb(NOT paused)
            OR prior.payload #> '{after,rule,stopped}' IS DISTINCT FROM to_jsonb(paused)
            -- A recorded boundary is an ISO instant when present and JSON null when the
            -- state was never held; a missing key or any other JSON type is tampering.
            OR coalesce(jsonb_typeof(prior.payload #> '{before,rule,stopped_at}'), 'absent')
                NOT IN ('string', 'null')
            OR coalesce(jsonb_typeof(prior.payload #> '{after,rule,stopped_at}'), 'absent')
                NOT IN ('string', 'null')
            OR (((prior.payload #>> '{before,rule,stopped_at}') IS NOT NULL)
                IS DISTINCT FROM (NOT paused))
            OR (((prior.payload #>> '{after,rule,stopped_at}') IS NOT NULL)
                IS DISTINCT FROM paused)
            -- The recorded boundary is deliberately not compared to the live rule row:
            -- a replay of an accepted pause must still succeed after a later resume, and
            -- the receipt always returns what that command originally recorded.
            THEN
            RAISE EXCEPTION 'Conflicting recurring Quest recurrence command reuse'
                USING ERRCODE = '23505';
        END IF;
        -- Attribution only: a retry may arrive under another valid origin, and the
        -- recorded payload is never rewritten (quest-creation-v1-contract.md).
        PERFORM progression_internal.require_origin(prior.payload ->> 'origin');
        RETURN (set_quest_recurrence_pause.command_id, prior.quest_id, prior_rule.id,
            definition.recurrence_mode, paused,
            (prior.payload #>> '{after,rule,stopped_at}')::timestamptz, prior.id, true);
    END IF;

    -- Accepted historical receipts above remain valid after retirement.
    PERFORM system_internal.reject_completion_alias(command_id);
    IF EXISTS (SELECT 1 FROM public.quest_events e
        WHERE e.user_id = actor AND e.command_id = set_quest_recurrence_pause.command_id) THEN
        RAISE EXCEPTION 'Conflicting recurring Quest recurrence command reuse' USING ERRCODE = '23505';
    END IF;
    IF definition.deleted_at IS NOT NULL OR definition.archived_at IS NOT NULL THEN
        RAISE EXCEPTION 'Retired recurring Quest cannot change pause state' USING ERRCODE = '23514';
    END IF;

    IF NOT paused THEN
        PERFORM system_internal.tzdb_context_v1(system_internal.tzdb_active_release_v1(),
            (SELECT p.timezone FROM public.profiles p WHERE p.user_id=actor));
    END IF;

    -- A fresh command that finds the definition already in the requested state writes
    -- nothing: no history row, no rule update. replay stays false because no command
    -- identity was recorded, and state_event_id is null so the caller can tell a no-op
    -- acknowledgement from a replay of an accepted command (RR-07).
    IF (rule.stopped_at IS NOT NULL) = paused THEN
        RETURN (set_quest_recurrence_pause.command_id, definition.id, rule.id,
            definition.recurrence_mode, paused, rule.stopped_at, NULL::uuid, false);
    END IF;

    v_now := now();
    v_stopped_at := CASE WHEN paused THEN v_now END;
    v_stopped_text := CASE WHEN paused THEN to_char(v_now AT TIME ZONE INTERVAL '0',
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END;
    v_previous_text := CASE WHEN rule.stopped_at IS NOT NULL THEN to_char(
        rule.stopped_at AT TIME ZONE INTERVAL '0', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END;
    v_event := gen_random_uuid();

    UPDATE public.quest_recurrence_rules AS r
        SET stopped_at = v_stopped_at, updated_at = v_now
        WHERE r.id = rule.id AND r.user_id = actor;
    UPDATE public.quests AS q
        SET updated_at = v_now
        WHERE q.id = definition.id AND q.user_id = actor;

        actor_user_id, occurred_at, command_id, payload_version, payload)
        VALUES (v_event, definition.id, actor, v_wanted_event, 'user', actor, v_now,
            set_quest_recurrence_pause.command_id, 1,
            jsonb_build_object('origin', origin,
                'before', jsonb_build_object('rule', jsonb_build_object(
                    'stopped', NOT paused, 'stopped_at', v_previous_text)),
                'after', jsonb_build_object('rule', jsonb_build_object(
                    'stopped', paused, 'stopped_at', v_stopped_text))));

    RETURN (set_quest_recurrence_pause.command_id, definition.id, rule.id,
        definition.recurrence_mode, paused, v_stopped_at, v_event, false);
END;
$function$;

ALTER FUNCTION public.materialize_quest_day_v2(date) OWNER TO quest_command_owner;
ALTER FUNCTION public.create_recurring_quest_v2(uuid,jsonb,text) OWNER TO quest_command_owner;
ALTER FUNCTION public.set_recurring_quest_schedule_defaults_v1(uuid,uuid,integer,time,time,smallint,text) OWNER TO quest_command_owner;
REVOKE CREATE ON SCHEMA public FROM quest_command_owner;
REVOKE ALL ON FUNCTION system_internal.valid_recurring_schedule_v1(time,time,smallint),
    system_internal.resolve_recurring_local_v1(timestamp,text),
    system_internal.recurring_rule_snapshot_v1(public.quest_recurrence_rules),
